macro.command:
// Finger of Death — Raise Zombie automation
// postActiveEffects: check for humanoids killed, raise as zombies

async function raiseZombies(casterActor, spellItem, targetTokenUuids) {
  const raiseActivity = spellItem.system.activities.find(
    a => a.identifier === "raise-zombie"
  );
  for (const tokenDocUuid of targetTokenUuids) {
    const tokenDoc = await fromUuid(tokenDocUuid);
    if (!tokenDoc) continue;
    const targetActor = tokenDoc.actor;
    const isDead = targetActor?.statuses?.has("dead")
      || targetActor?.statuses?.has("defeated");
    if (!isDead) continue;
    await MidiQOL.socket().executeAsGM("toggleTokenHidden", { tokenUuid: tokenDoc.uuid, force: true });
    if (raiseActivity) {
      await MidiQOL.socket().executeAsGM("completeActivityUse", {
        activityUuid: raiseActivity.uuid,
        actorUuid: casterActor.uuid,
        usage: {
          summons: {
            placements: [{
              x: tokenDoc.x,
              y: tokenDoc.y,
              elevation: tokenDoc.elevation
            }]
          }
        },
        dialog: {},
        message: {}
      });
    }
  }
}

if (args[0]?.macroPass === "postActiveEffects") {
  const validTargets = [];
  for (const entry of workflow.damageList) {
    if (entry.newHP > 0) continue;
    const targetActor = await fromUuid(entry.actorUuid);
    if (!targetActor) continue;
    const creatureType = targetActor.system?.details?.type?.value?.toLowerCase();
    if (creatureType !== "humanoid") continue;
    validTargets.push(entry.targetUuid);
  }
  if (validTargets.length === 0) return;

  const inCombat = !!game.combat?.started;
  if (!inCombat) {
    await raiseZombies(actor, item, validTargets);
  } else {
    await actor.setFlag("midi-qol", "fingerOfDeathTargets", validTargets);
    function cleanup() {
      Hooks.off("updateCombat", updateHookId);
      Hooks.off("deleteCombat", deleteHookId);
      delete globalThis._midiFingerOfDeathHooks?.[actor.uuid];
      actor.unsetFlag("midi-qol", "fingerOfDeathTargets");
    }
    const updateHookId = Hooks.on("updateCombat", async (combat, data, options, userId) => {
      if (data.round === undefined && data.turn === undefined) return;
      const combatant = combat.combatant;
      if (combatant?.actor?.uuid !== actor.uuid) return;
      const targets = actor.getFlag("midi-qol", "fingerOfDeathTargets") ?? [];
      const toRaise = [];
      const stillPending = [];
      for (const tokenUuid of targets) {
        const tokenDoc = await fromUuid(tokenUuid);
        if (!tokenDoc?.actor) continue;
        const hp = tokenDoc.actor.system.attributes.hp.value;
        const isDead = tokenDoc.actor.statuses?.has("dead") || tokenDoc.actor.statuses?.has("defeated");
        if (hp > 0) continue;
        if (isDead) { toRaise.push(tokenUuid); }
        else { stillPending.push(tokenUuid); }
      }
      if (toRaise.length) await raiseZombies(actor, item, toRaise);
      if (stillPending.length) {
        await actor.setFlag("midi-qol", "fingerOfDeathTargets", stillPending);
      } else {
        cleanup();
      }
    });
    const deleteHookId = Hooks.on("deleteCombat", () => {
      cleanup();
    });
    globalThis._midiFingerOfDeathHooks ??= {};
    globalThis._midiFingerOfDeathHooks[actor.uuid] = { updateHookId, deleteHookId };
  }
}
